//! The edge paths and line hops of the flowchart against the reference.
//!
//! `fixtures/flowchart-edge-paths.json` holds the `d` strings that the reference's `insertEdge`
//! (run in jsdom) and `processEdgesWithJumps` write for fifty-four edge point lists and twenty-six
//! hop rewrites. It is regenerated by `pnpm run port:edge-paths` (`tools/port/export-flowchart-edges.ts`).
//! Paths written with full precision (`rounded`) are compared as numbers within 1e-9; paths written
//! with three digits (d3 curves) and the hops must match as text.

use ferrigura_model::config::MermaidConfig;
use ferrigura_model::flowchart::LabelType;
use ferrigura_render::unified::data::Edge;
use ferrigura_render::unified::edges::paint_paths;
use ferrigura_render::unified::geom::Point;
use ferrigura_render::unified::line_jumps::{
    EdgeGeom, JumpStyle, LineJumpConfig, find_edge_intersections, rewrite_edge_path,
};
use ferrigura_render::unified::markers::FLOWCHART;

const FIXTURE: &str = include_str!("fixtures/flowchart-edge-paths.json");

fn point(value: &serde_json::Value) -> Point {
    Point::new(
        value["x"].as_f64().expect("x"),
        value["y"].as_f64().expect("y"),
    )
}

fn points(value: &serde_json::Value) -> Vec<Point> {
    value
        .as_array()
        .expect("points")
        .iter()
        .map(point)
        .collect()
}

/// The `d` attribute of the `<path>` element in an edge's SVG.
fn d_attribute(svg: &str) -> Option<String> {
    let start = svg.find(" d=\"")? + " d=\"".len();
    let end = svg[start..].find('"')?;
    Some(svg[start..start + end].to_owned())
}

/// Splits a path into its command letters and the numbers that follow each of them.
fn commands(d: &str) -> Vec<(char, Vec<f64>)> {
    let mut out: Vec<(char, Vec<f64>)> = Vec::new();
    let mut numbers = String::new();
    let flush = |numbers: &mut String, out: &mut Vec<(char, Vec<f64>)>| {
        if !numbers.is_empty() {
            let value: f64 = numbers.parse().expect("a number");
            out.last_mut()
                .expect("a command before a number")
                .1
                .push(value);
            numbers.clear();
        }
    };
    for c in d.chars() {
        let exponent = (c == 'e' || c == 'E') && !numbers.is_empty();
        let sign_after_number = c == '-' && !numbers.is_empty() && !numbers.ends_with(['e', 'E']);
        if sign_after_number {
            flush(&mut numbers, &mut out);
        }
        if c.is_ascii_alphabetic() && !exponent {
            flush(&mut numbers, &mut out);
            out.push((c, Vec::new()));
        } else if c == ',' || c.is_whitespace() {
            flush(&mut numbers, &mut out);
        } else {
            numbers.push(c);
        }
    }
    flush(&mut numbers, &mut out);
    out
}

/// Whether two paths agree, with numbers compared within `tolerance` and the text otherwise.
fn same_path(actual: &str, expected: &str, tolerance: f64) -> bool {
    let (a, e) = (commands(actual), commands(expected));
    a.len() == e.len()
        && a.iter().zip(&e).all(|((ca, na), (ce, ne))| {
            ca == ce
                && na.len() == ne.len()
                && na
                    .iter()
                    .zip(ne)
                    .all(|(x, y)| (x - y).abs() <= tolerance || x == y)
        })
}

fn edge_from(case: &serde_json::Value) -> Edge {
    Edge {
        id: case["id"].as_str().expect("id").to_owned(),
        start: "a".to_owned(),
        end: "b".to_owned(),
        edge_type: "arrow_point".to_owned(),
        label_type: LabelType::Text,
        classes: "flowchart-link".to_owned(),
        thickness: "normal".to_owned(),
        pattern: "solid".to_owned(),
        look: "classic".to_owned(),
        labelpos: "c".to_owned(),
        arrow_type_start: case["arrowTypeStart"].as_str().expect("start").to_owned(),
        arrow_type_end: case["arrowTypeEnd"].as_str().expect("end").to_owned(),
        curve: Some(case["curve"].as_str().expect("curve").to_owned()),
        points: points(&case["points"]),
        ..Edge::default()
    }
}

#[test]
fn the_paths_match_the_reference() {
    let fixture: serde_json::Value = serde_json::from_str(FIXTURE).expect("the fixture parses");
    let config = MermaidConfig::default();
    let cases = fixture["paths"].as_array().expect("paths");
    assert!(cases.len() >= 50, "{} path cases", cases.len());
    let mut failures = Vec::new();
    for case in cases {
        let edge = edge_from(case);
        let painted = paint_paths(std::slice::from_ref(&edge), "svg", FLOWCHART, &config);
        let actual = d_attribute(&painted[0].svg);
        let expected = case["d"].as_str().expect("d");
        let rounded = case["curve"].as_str() == Some("rounded");
        let matches = match &actual {
            Some(actual) => same_path(actual, expected, if rounded { 1e-9 } else { 0.0 }),
            None => expected.is_empty(),
        };
        if !matches {
            failures.push(format!("{}: expected {expected}, got {actual:?}", edge.id));
        }
    }
    assert!(
        failures.is_empty(),
        "{} failures:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

#[test]
fn the_line_hops_match_the_reference() {
    let fixture: serde_json::Value = serde_json::from_str(FIXTURE).expect("the fixture parses");
    let groups = fixture["lineHops"].as_array().expect("lineHops");
    let mut checked = 0;
    let mut failures = Vec::new();
    for group in groups {
        let style = match group["jumpStyle"].as_str() {
            Some("gap") => JumpStyle::Gap,
            _ => JumpStyle::Arc,
        };
        let config = LineJumpConfig {
            jump_radius: 6.0,
            jump_style: style,
        };
        let edges: Vec<EdgeGeom> = group["edges"]
            .as_array()
            .expect("edges")
            .iter()
            .map(|edge| EdgeGeom {
                id: edge["id"].as_str().expect("id").to_owned(),
                points: points(&edge["points"]),
                curve: edge["curve"].as_str().map(str::to_owned),
                arrow_type_start: edge["arrowTypeStart"].as_str().expect("start").to_owned(),
                arrow_type_end: edge["arrowTypeEnd"].as_str().expect("end").to_owned(),
                style: String::new(),
            })
            .collect();
        let expected = group["expected"].as_object().expect("expected");
        let crossings = find_edge_intersections(&edges);
        let mut jumping: Vec<usize> = crossings.iter().map(|c| c.jump_edge).collect();
        jumping.sort_unstable();
        jumping.dedup();
        let jumping_ids: std::collections::BTreeSet<&str> = jumping
            .iter()
            .map(|&index| edges[index].id.as_str())
            .collect();
        let expected_ids: std::collections::BTreeSet<&str> =
            expected.keys().map(String::as_str).collect();
        if jumping_ids != expected_ids {
            failures.push(format!(
                "{}: jumping edges {jumping_ids:?}, expected {expected_ids:?}",
                group["id"]
            ));
        }
        for index in jumping {
            let edge = &edges[index];
            let jumps: Vec<_> = crossings
                .iter()
                .filter(|crossing| crossing.jump_edge == index)
                .cloned()
                .collect();
            let actual = rewrite_edge_path(edge, &jumps, &config);
            let Some(expected) = expected.get(&edge.id).and_then(|value| value.as_str()) else {
                continue;
            };
            checked += 1;
            if actual != expected {
                failures.push(format!(
                    "{} {}: expected {expected}, got {actual}",
                    group["id"], edge.id
                ));
            }
        }
    }
    assert!(checked >= 20, "{checked} hop rewrites checked");
    assert!(
        failures.is_empty(),
        "{} failures:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

/// A neo edge of the default flowchart, as the reference's capture of `nightly-check-02` writes it:
/// `d` ends 4 px before its last point, the dash array hides those 4 px, and the arrow is the neo
/// margin variant. The class repeats the thickness and pattern classes, as `flowDb` gives them.
#[test]
fn a_neo_edge_matches_the_reference_svg() {
    let edge = Edge {
        id: "L_A_B_0".to_owned(),
        start: "A".to_owned(),
        end: "B".to_owned(),
        edge_type: "arrow_point".to_owned(),
        label_type: LabelType::Text,
        classes: "edge-thickness-normal edge-pattern-solid flowchart-link".to_owned(),
        thickness: "normal".to_owned(),
        pattern: "normal".to_owned(),
        look: "neo".to_owned(),
        labelpos: "c".to_owned(),
        arrow_type_start: "none".to_owned(),
        arrow_type_end: "arrow_point".to_owned(),
        curve: Some("rounded".to_owned()),
        points: vec![Point::new(280.0, 53.0), Point::new(280.0, 154.0)],
        ..Edge::default()
    };
    let painted = paint_paths(
        std::slice::from_ref(&edge),
        "svg",
        FLOWCHART,
        &MermaidConfig::default(),
    );
    let svg = &painted[0].svg;
    assert!(svg.contains(" d=\"M280,53L280,150\""), "{svg}");
    assert!(
        svg.contains(
            " class=\" edge-thickness-normal edge-pattern-solid edge-thickness-normal edge-pattern-solid flowchart-link\""
        ),
        "{svg}"
    );
    assert!(
        svg.contains(" style=\"stroke-dasharray: 0 0 93 4; stroke-dashoffset: 0;;\""),
        "{svg}"
    );
    assert!(svg.contains(" data-look=\"neo\""), "{svg}");
    assert!(
        svg.contains(" marker-end=\"url(#svg_flowchart-v2-pointEnd-margin)\""),
        "{svg}"
    );
    assert!(!svg.contains("marker-start"), "{svg}");
    assert_eq!(
        painted[0].bbox.height,
        150.0 - 53.0,
        "{:?}",
        painted[0].bbox
    );
}
